insert into public.roadmap_details (
  node_id, title, days, description, resources, criteria,
  why, tasks, common_mistakes, source_support_rate, category
) values
  (
    'ai-ap-n-format',
    '科目A・Bの時間と合格基準を確認する',
    1,
    '科目Aは150分80問の四肢択一、科目Bは150分で11問中5問の記述です。どちらも100点中60点が必要です。',
    '[{"label":"IPA 応用情報技術者試験","url":"https://www.ipa.go.jp/shiken/kubun/ap.html","note":"時間・問数・対象者像の公式案内です。"},{"label":"令和8年度の実施予定","url":"https://www.ipa.go.jp/shiken/2026/ap_koudo_sc_yotei.html","note":"CBT化と科目名称の変更、出題範囲は変わらないことが書いてあります。"}]'::jsonb,
    '["両方60点が必要なことと、問1が必須であることを説明できる"]'::jsonb,
    '22件中20件が、午前・午後の名前が科目A・Bに変わっても、問数と時間は同じだと前提にしていました。2026年度はCBTの前期・後期です。基本情報の科目B（擬似言語）とは別物です。',
    '["科目A 80問150分、科目B 11問中5問150分、両方60点以上だと覚える","科目Bの問1が情報セキュリティの必須だと確認する","手元の本が現行の出題に対応しているかを確認する"]'::jsonb,
    '["基本情報の科目B対策本を応用情報の記述対策だと思う","科目Aだけ仕上げて記述を直前期に残す"]'::jsonb,
    '20/22（91%）',
    '試験形式'
  ),
  (
    'ai-ap-n-kakomon-a',
    '科目Aは過去問道場を周回する',
    28,
    '基本情報合格者はテキストの通読より、過去問で穴を見つけて教科書に戻る方が速い、という指摘が重なっていました。',
    '[{"label":"応用情報技術者過去問道場","url":"https://www.ap-siken.com/apkakomon.php","note":"科目A（旧午前）の反復用です。選択肢シャッフルがあると暗記になりにくいです。"},{"label":"令和08年 応用情報技術者 合格教本","url":"https://direct.gihyo.jp/view/item/000000003962","note":"調べる教科書です。最初から通読する必要はありません。DEKIDAS-Webが付きます。"}]'::jsonb,
    '["分野別で弱い領域のメモがある","直近数年の科目Aを、解説を読んで2周以上している"]'::jsonb,
    '22件中20件が、科目Aは過去問の流用と類題が多いと書いていました。正解だけでなく、誤選択肢がどの場面の話かも説明できるまで繰り返します。わからない論点だけ合格教本で調べます。',
    '["過去問道場を分野別で1周し、正答率が低い分野に印を付ける","間違えた問題は、正解と誤選択肢の両方を自分の言葉で言い直す","用語が浮かばないときだけ、合格教本の該当章を読む"]'::jsonb,
    '["教科書を全部読んでから過去問に入る","正解番号だけ覚えて、誤選択肢を読まない"]'::jsonb,
    '20/22（91%）',
    '知識'
  ),
  (
    'ai-ap-n-sec',
    '問1の情報セキュリティを先に取る',
    10,
    '科目Bの問1は情報セキュリティの必須です。選択分野より先に、設問の読み方と字数の感覚を作ります。',
    '[{"label":"IPA 問題冊子・解答例・採点講評","url":"https://www.ipa.go.jp/shiken/mondai-kaiotu/2025r07.html","note":"公式の解答例と講評です。書き方の基準に使います。"},{"label":"午後問1の解説（試験.com）","url":"https://www.ap-siken.com/kakomon/06_haru/pm01.html","note":"事例の読み方を日本語で追う補助です。公式PDFとセットで使います。"}]'::jsonb,
    '["問1を時間を測って3回以上書いている","講評の観点で、自分の答案の抜けを指摘できる"]'::jsonb,
    '22件中19件が、問1を落として選択問題で挽回する設計は危ないと書いていました。ゼロトラストやインシデント対応など、事例の要点を短く書く練習が共通しています。',
    '["直近数年の問1を、解答例を見る前に自分で書く","採点講評で、求められている字数と観点を確認する","同じ問題を、講評の言葉で書き直す"]'::jsonb,
    '["問1を読んだだけで書かず、選択分野の暗記に逃げる","解答例を写してできた気になる"]'::jsonb,
    '19/22（86%）',
    '記述'
  ),
  (
    'ai-ap-n-choice',
    '得意分野を5〜6個に絞って毎週書く',
    28,
    '本番は必須1問＋選択4問です。プログラミング、データベース、ネットワークなど、書ける分野を先に固定します。',
    '[{"label":"情報処理教科書 応用情報 テキスト＆問題集","url":"https://www.shoeisha.co.jp/book/detail/9784798194424","note":"午後の演習と解説が1冊に入っています。選択分野の型取りに使います。"},{"label":"応用情報技術者過去問道場（午後）","url":"https://www.ap-siken.com/apkakomon.php","note":"分野を指定して回せます。答案は別紙に書いてから解説を開きます。"}]'::jsonb,
